import{_ as l,K as s,a as p,c as o,ac as t,q as i,b as e,k as n}from"./chunks/framework.BSuaGltH.js";const C=JSON.parse('{"title":"进程、内存与持久性的工作方式","description":"进程线程、特权切换、分页、并发死锁和文件持久性的机制与排错。","frontmatter":{"title":"进程、内存与持久性的工作方式","description":"进程线程、特权切换、分页、并发死锁和文件持久性的机制与排错。","showdocs":{"topics":[{"id":"fundamentals","title":"操作系统原理","link":"/topics/fundamentals/"}],"kind":"资源与计算机制","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"操作系统原理：模型与推演","summary":"进程线程、特权切换、分页、并发死锁和文件持久性的机制与排错。","status":"active","related":[{"title":"操作系统（02323）：概念与资源管理笔记","link":"/principles/fundamentals/operatingsystems","kind":"持久性与参考","scope":"general","audience":"general"},{"title":"操作系统（02323）：概念与资源管理笔记 · 操作系统概论至概念与资源","link":"/principles/fundamentals/operatingsystems-part-01","kind":"持久性与参考","scope":"general","audience":"general"},{"title":"操作系统（02323）：概念与资源管理笔记 · 进程与调度至I/O 设备管理","link":"/principles/fundamentals/operatingsystems-part-02","kind":"持久性与参考","scope":"general","audience":"general"},{"title":"操作系统复习题与易错点","link":"/principles/fundamentals/operatingsystemserror","kind":"调度与并发推演","scope":"general","audience":"general"},{"title":"操作系统复习题与易错点 · 操作系统概论复习至知识摘录速查","link":"/principles/fundamentals/operatingsystemserror-part-01","kind":"调度与并发推演","scope":"general","audience":"general"}],"prev":false,"next":{"text":"轮转调度推演与练习","link":"/principles/fundamentals/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"轮转调度推演与练习","link":"/principles/fundamentals/application"}},"headers":[],"relativePath":"principles/fundamentals/operating-system-mechanisms.md","filePath":"principles/fundamentals/operating-system-mechanisms.md"}'),d={name:"principles/fundamentals/operating-system-mechanisms.md"};function u(m,a,I,h,g,c){const r=s("Mermaid");return p(),o("div",null,[a[0]||(a[0]=t('<h1 id="进程、内存与持久性的工作方式" tabindex="-1">进程、内存与持久性的工作方式 <a class="header-anchor" href="#进程、内存与持久性的工作方式" aria-label="Permalink to &quot;进程、内存与持久性的工作方式&quot;">​</a></h1><h2 id="part-1" tabindex="-1">进程、线程与调度 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;进程、线程与调度 {#part-1}&quot;">​</a></h2><p><span id="part-1-操作系统原理-问题、表示与约束"></span></p><p>前置：能区分进程、线程、就绪与阻塞，理解队列和时间片；Python 3.10+ 仅用于轮转调度模型。教学范围为OSTEP虚拟化/并发/持久化模型；Python 3.10+。核对日期2026-10-17。示例未执行，本轮没有安装依赖、生成协议代码、启动服务或浏览器预览。完整文件与输入见<a href="/principles/fundamentals/application">轮转调度模型、输入与练习</a>；推演结论只适用于写明的模型。</p><h3 id="part-1-process" tabindex="-1">进程与线程共享什么 <a class="header-anchor" href="#part-1-process" aria-label="Permalink to &quot;进程与线程共享什么 {#part-1-process}&quot;">​</a></h3><p>两个线程处理同一进程的计数器时会访问相同堆地址，但各自暂停位置与局部调用链不同。单核可以交错执行两个线程，多核才可能在同一瞬间并行；共享地址不代表共享数据自动免于竞争。</p>',6)),i(r,{source:"Zmxvd2NoYXJ0IFRECiBBWyLov5vnqIvlnLDlnYDnqbrpl7QiXSAtLT4gSFsi5YWx5Lqr5aCG5LiO5YWo5bGA5Y+Y6YePIl0KIEEgLS0+IFQxWyLnur/nqIsx77ya54us56uL5a+E5a2Y5Zmo5LiO5qCIIl0KIEEgLS0+IFQyWyLnur/nqIsy77ya54us56uL5a+E5a2Y5Zmo5LiO5qCIIl0KIFQxIC0tPiBICiBUMiAtLT4gSAo="}),a[1]||(a[1]=e("p",null,"进程与线程共享什么首先区分地址空间与执行上下文。同进程线程通常共享堆与全局数据，各自有寄存器和栈；进程隔离也可通过显式共享内存打通。线程数不是可同时占用CPU核数，并发与并行也不是同一个概念。",-1)),a[2]||(a[2]=e("h3",{id:"part-1-privilege",tabindex:"-1"},[n("系统调用为什么切换 "),e("a",{class:"header-anchor",href:"#part-1-privilege","aria-label":'Permalink to "系统调用为什么切换 {#part-1-privilege}"'},"​")],-1)),a[3]||(a[3]=e("p",null,"一次立即完成的系统调用可以始终由同一个线程执行。只有需要等待或被抢占等情况，调度器才可能选择另一个线程；因此不能把用户态进入内核态等同于任务更换。",-1)),i(r,{source:"Zmxvd2NoYXJ0IExSCiBBWyLnur/nqItB55So5oi35oCBIl0gLS0+IEJbIuWPl+aOp+ezu+e7n+iwg+eUqOWFpeWPoyJdCiBCIC0tPiBDWyLnur/nqItB5YaF5qC45oCB5aSE55CGIl0KIEMgLS0+IERbIui/lOWbnue6v+eoi0HnlKjmiLfmgIEiXQogQyAtLiAi6Iul6Zi75aGe562J5b6FIiAuLT4gRVsi6LCD5bqm5YW25LuW5bCx57uq57q/56iLIl0K"}),a[4]||(a[4]=t('<p>系统调用为什么切换：普通代码不能任意改页表或设备状态，受控入口进入内核处理特权操作。模式切换不必更换进程，进程上下文切换则还需恢复调度对象状态；不能把每次函数调用都算成系统调用。</p><h3 id="part-1-schedule" tabindex="-1">轮转调度计算模型 <a class="header-anchor" href="#part-1-schedule" aria-label="Permalink to &quot;轮转调度计算模型 {#part-1-schedule}&quot;">​</a></h3><p>轮转调度计算模型给就绪任务一个有限时间片，用完移到队尾。本文假设任务均在时刻0到达、单CPU、无IO和切换开销，因而能手算公平性；真实调度器还需优先级、唤醒和多核亲和，不能用教学输出预测Linux时延。</p><h4 id="part-1-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-1-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-1-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://pages.cs.wisc.edu/~remzi/OSTEP/" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://pages.cs.wisc.edu/~remzi/OSTEP/Chinese/" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li></ul><h2 id="part-2" tabindex="-1">虚拟内存、并发与死锁 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;虚拟内存、并发与死锁 {#part-2}&quot;">​</a></h2><p><span id="part-2-操作系统原理-机制、交互与代价"></span></p><h3 id="part-2-memory" tabindex="-1">分页与地址转换 <a class="header-anchor" href="#part-2-memory" aria-label="Permalink to &quot;分页与地址转换 {#part-2-memory}&quot;">​</a></h3><p>页大小4KiB时，虚拟地址0x1234拆为页号1、偏移0x234。若页表把虚拟页1映到物理页框9，物理地址就是0x9234。TLB未命中时页表仍可能给出有效映射，不需要从磁盘读取。</p>',9)),i(r,{source:""}),a[5]||(a[5]=e("p",null,"分页与地址转换把虚拟地址拆成页号和页内偏移，通过页表找物理页。TLB缓存翻译结果，TLB未命中并不必然缺页；缺页意味着映射或权限需要内核处理，可能是合法按需分配也可能终止进程。",-1)),a[6]||(a[6]=e("h3",{id:"part-2-race",tabindex:"-1"},[n("丢更新与临界区 "),e("a",{class:"header-anchor",href:"#part-2-race","aria-label":'Permalink to "丢更新与临界区 {#part-2-race}"'},"​")],-1)),a[7]||(a[7]=e("p",null,"下图是一种合法交错，最终只有1而非2。要保护的是读取、计算、写回整体；锁住两个独立的写回动作仍无法修复此前读到旧值的问题。原子递增也必须符合相应语言的同步规则。",-1)),i(r,{source:"c2VxdWVuY2VEaWFncmFtCiBwYXJ0aWNpcGFudCBBIGFzIOe6v+eoi0EKIHBhcnRpY2lwYW50IFggYXMg5YWx5LqreAogcGFydGljaXBhbnQgQiBhcyDnur/nqItCCiBBLT4+WDog6K+75Y+WMAogQi0+Plg6IOivu+WPljAKIEEtPj5YOiDlhpnlm54xCiBCLT4+WDog5YaZ5ZueMe+8jOimhueblkHnmoTmm7TmlrAK"}),a[8]||(a[8]=e("p",null,"丢更新与临界区可手推：两个线程都读到0，各自加1再写回1。读改写不是单个原子操作，需要互斥或适当原子协议覆盖完整临界区。只给写操作加锁仍允许两个线程先读旧值，内存可见性也需语言内存模型约束。",-1)),a[9]||(a[9]=e("h3",{id:"part-2-deadlock",tabindex:"-1"},[n("死锁四条件与顺序 "),e("a",{class:"header-anchor",href:"#part-2-deadlock","aria-label":'Permalink to "死锁四条件与顺序 {#part-2-deadlock}"'},"​")],-1)),a[10]||(a[10]=e("p",null,"假设两把不可重入互斥锁，每把只有一个持有者，线程不会主动释放已持锁。A持L1等L2，B持L2等L1形成等待环。若全部线程始终先取L1再取L2，B无法先持L2，下面这个环就无法形成。",-1)),i(r,{source:"Zmxvd2NoYXJ0IExSCiBBWyLnur/nqItBIl0gLS0+fCLnrYnlvoUifCBMMlsi6ZSBTDIiXQogTDIgLS0+fCLnlLHlhbbmjIHmnIkifCBCWyLnur/nqItCIl0KIEIgLS0+fCLnrYnlvoUifCBMMVsi6ZSBTDEiXQogTDEgLS0+fCLnlLHlhbbmjIHmnIkifCBBCg=="}),a[11]||(a[11]=t('<p>死锁四条件与顺序包括互斥、占有等待、不可剥夺与循环等待。给资源全局顺序并始终按序获取可以破坏循环等待；超时只是退出策略，未释放已持资源会继续阻塞。饥饿不一定形成环，需要另查调度与公平性。</p><h4 id="part-2-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-2-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-2-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://pages.cs.wisc.edu/~remzi/OSTEP/" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://pages.cs.wisc.edu/~remzi/OSTEP/Chinese/" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li></ul><h2 id="part-3" tabindex="-1">文件持久性与操作系统排错 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;文件持久性与操作系统排错 {#part-3}&quot;">​</a></h2><p><span id="part-3-操作系统原理-反例、取舍与原文"></span></p><h3 id="part-3-durability" tabindex="-1">文件持久性边界 <a class="header-anchor" href="#part-3-durability" aria-label="Permalink to &quot;文件持久性边界 {#part-3-durability}&quot;">​</a></h3><p>图中每个箭头都跨越不同缓冲边界。write成功通常先表示内核接收字节，持久化接口要求把相关状态推进到所承诺的存储边界；原子替换还要考虑目录项。具体保证由文件系统、接口和设备决定，不能仅靠一次close推断掉电结果。</p>',7)),i(r,{source:"Zmxvd2NoYXJ0IExSCiBBWyLlupTnlKjnvJPlhrIiXSAtLT4gQlsi5YaF5qC46aG157yT5a2YIl0KIEIgLS0+IENbIuiuvuWkh+mYn+WIl+S4jue8k+WtmCJdCiBDIC0tPiBEWyLnqLPlrprlrZjlgqgiXQo="}),a[12]||(a[12]=t('<p>文件持久性边界针对崩溃模型，要区分应用缓存、内核缓存与稳定存储。写入函数返回不意味着断电后一定保留，原子替换文件还涉及文件内容与目录项的持久顺序。日志恢复修复的是规定故障模型中的一致性，不能代替备份。</p><h3 id="part-3-diagnosis" tabindex="-1">操作系统现象证据 <a class="header-anchor" href="#part-3-diagnosis" aria-label="Permalink to &quot;操作系统现象证据 {#part-3-diagnosis}&quot;">​</a></h3><p>操作系统现象证据应区分任务正在运行、可运行但排队，或阻塞等IO。CPU低并不能证明程序空闲，可能所有线程等锁；内存占用也不能直接当泄漏，缓存与映射需分别解释。本轮只手推模型，无系统性能采样。</p><h3 id="part-3-sources" tabindex="-1">操作系统阅读边界 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;操作系统阅读边界 {#part-3-sources}&quot;">​</a></h3><p>操作系统阅读边界采用作者英文OSTEP与作者站点中文译本，围绕虚拟化、并发和持久化。历史自考笔记仍作为考试资料保留，错误题集不是当前内核规范；新课不将考试口径推广为所有平台行为。</p><h4 id="part-3-来源与适用边界" tabindex="-1">来源与适用边界 <a class="header-anchor" href="#part-3-来源与适用边界" aria-label="Permalink to &quot;来源与适用边界 {#part-3-来源与适用边界}&quot;">​</a></h4><ul><li><a href="https://pages.cs.wisc.edu/~remzi/OSTEP/" target="_blank" rel="noopener noreferrer">英文官方、作者或规范原文</a>：本专题机制依据；按上述固定版本族阅读。</li><li><a href="https://pages.cs.wisc.edu/~remzi/OSTEP/Chinese/" target="_blank" rel="noopener noreferrer">中文官方或作者资料</a>：用于术语和讲解交叉核对，冲突以原始规范为准。</li><li><a href="/principles/fundamentals/operatingsystems">相关既有参考</a>：原URL与专业范围保留；历史案例不能自动代表当前实现。</li></ul>',7))])}const f=l(d,[["render",u]]);export{C as __pageData,f as default};
